              countingValidPipe('B', calls),
            ]),
          ],
          true,
        )!;

        const okArgs: unknown[] = [undefined, undefined];
        await pipesFn(okArgs, {}, {}, () => {});
        expect(okArgs).toEqual([7, 10]);

        idValue = 'abc';
        limitValue = 'x';
        let error: BadRequestException;
        try {
          await pipesFn([undefined, undefined], {}, {}, () => {});
        } catch (e) {
